826	+func addLefthookLocalConfigToGitExclude(ctx context.Context, repoRoot, localConfigPath string) error {
827	+	relPath, err := filepath.Rel(repoRoot, localConfigPath)
828	+	if err != nil {
829	+		return fmt.Errorf("make Lefthook local config path relative: %w", err)
830	+	}
831	+	relPath = filepath.ToSlash(relPath)
832	+
833	+	gitDir, err := GetGitDir(ctx)
834	+	if err != nil {
835	+		return err
836	+	}
837	+	excludePath := filepath.Join(gitDir, "info", "exclude")
838	+	if err := os.MkdirAll(filepath.Dir(excludePath), 0o750); err != nil {
839	+		return fmt.Errorf("create git info directory: %w", err)
840	+	}
841	+
842	+	data, err := os.ReadFile(excludePath) //nolint:gosec // path is derived from git dir
843	+	if err == nil {
844	+		for _, line := range strings.Split(string(data), "\n") {
845	+			if strings.TrimSpace(line) == relPath {
846	+				return nil
847	+			}
848	+		}
849	+	} else if !os.IsNotExist(err) {
850	+		return fmt.Errorf("read git exclude file %s: %w", excludePath, err)
851	+	}
852	+
853	+	f, err := os.OpenFile(excludePath, os.O_CREATE|os.O_APPEND|os.O_WRONLY, 0o644) //nolint:gosec // git info/exclude is a regular text file
854	+	if err != nil {
855	+		return fmt.Errorf("open git exclude file %s: %w", excludePath, err)
856	+	}
857	+	defer f.Close()
858	+
859	+	if len(data) > 0 && !strings.HasSuffix(string(data), "\n") {
860	+		if _, err := f.WriteString("\n"); err != nil {
861	+			return fmt.Errorf("append newline to git exclude file %s: %w", excludePath, err)
862	+		}
863	+	}
864	+	if _, err := fmt.Fprintln(f, relPath); err != nil {
865	+		return fmt.Errorf("append Lefthook local config to git exclude file %s: %w", excludePath, err)
866	+	}
867	+	return nil
868	+}
